Now I have everything I need. Here's how to build your MCP server:

---

### **Program.cs** — stdio transport with DI

```csharp
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

// CRITICAL: log to stderr only — stdout is the JSON-RPC channel
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

builder.Services.AddHttpClient();  // registers IHttpClientFactory + HttpClient

builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();      // auto-discovers [McpServerToolType] classes

await builder.Build().RunAsync();
```

### **ApiTools.cs** — tool class wrapping a REST API

```csharp
using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Fetch a user by their ID.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        return await httpClient.GetStringAsync(
            $"https://jsonplaceholder.typicode.com/users/{userId}",
            cancellationToken);
    }

    [McpServerTool, Description("List posts, optionally filtered by user.")]
    public async Task<string> ListPosts(
        [Description("Filter posts by this user ID (optional)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = userId.HasValue
            ? $"https://jsonplaceholder.typicode.com/posts?userId={userId}"
            : "https://jsonplaceholder.typicode.com/posts";

        return await httpClient.GetStringAsync(url, cancellationToken);
    }

    [McpServerTool, Description("Create a new post.")]
    public async Task<string> CreatePost(
        [Description("Title of the post")] string title,
        [Description("Body content of the post")] string body,
        [Description("Author's user ID")] int authorUserId,
        CancellationToken cancellationToken = default)
    {
        var payload = JsonSerializer.Serialize(new { title, body, userId = authorUserId });
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");

        var response = await httpClient.PostAsync(
            "https://jsonplaceholder.typicode.com/posts", content, cancellationToken);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}
```

---

### How DI works for MCP tools

The SDK supports **two injection styles**:

| Style | Class type | How services are injected |
|-------|-----------|--------------------------|
| **Constructor injection** | Non-static class (shown above) | Services like `HttpClient`, `ILogger<T>` are injected via primary constructor. The class is resolved from DI per invocation. |
| **Method parameter injection** | Static class | DI services appear as method parameters alongside tool parameters. |

**Key rule:** The SDK automatically distinguishes DI services from tool parameters. Only parameters with `[Description]` appear in the tool schema visible to the LLM. Types like `CancellationToken`, `IMcpServer`, `IProgress<T>`, and any DI-registered service are resolved automatically and hidden from the schema.

So in the example above, `HttpClient` and `ILogger<ApiTools>` are injected by the container — the LLM only sees `userId`, `title`, `body`, etc.
